 @Override Map<String,Object> snapshot(ModernSettlementMysqlFixture mysql,String label)throws Exception{
  var core=super.snapshot(mysql,label);for(String db:List.of(A,B)){var c=(Map<String,Object>)core.get(db);c.put("house_clans",rows(mysql,db,"SELECT clan_id,clan_name,leader_id,leader_name,hascastle,hashouse FROM clan_data ORDER BY clan_id"));c.put("house_record",rows(mysql,db,"SELECT house_id,house_name,is_on_sale,UNIX_TIMESTAMP(tax_deadline) AS tax_deadline FROM `server_盟屋_紀錄` ORDER BY house_id"));c.put("house_auction",rows(mysql,db,"SELECT house_id,UNIX_TIMESTAMP(deadline) AS deadline,price,old_owner,old_owner_id,bidder,bidder_id FROM `server_盟屋_拍賣` ORDER BY house_id"));c.put("house_revision",rows(mysql,db,"SELECT * FROM lito_house_auction_metadata ORDER BY house_id"));c.put("item_origin",rows(mysql,db,"SELECT item_obj_id,char_obj_id,catalog_id,tournament_reward FROM lito_item_origin ORDER BY item_obj_id"));}var last=(Map<String,Object>)snapshots.get(snapshots.size()-1);last.put("observed_utc",Instant.now().toString());last.put("epoch_seconds",System.currentTimeMillis()/1000);Files.writeString(root.resolve("snapshots").resolve(label+".json"),json(last),StandardCharsets.UTF_8);save();return core;
 }
 Actor self(Peer p,String alias){for(int i=p.received.size()-1;i>=0;i--){byte[] x=p.received.get(i);if((x[0]&255)==Protocol.S_PUT_OBJECT){Actor a=actor(x);if(a.name().equals(alias))return a;}}throw new AssertionError("actual actor absent "+alias);}
 long adena(Peer p){return p.inventory.values().stream().filter(x->x.icon()==5).mapToLong(Item::quantity).sum();}
 long sqlAdena(ModernSettlementMysqlFixture mysql,int id)throws Exception{return scalar(mysql,B,"SELECT COALESCE(SUM(count),0) FROM character_items WHERE char_id="+id+" AND item_id=40308");}
 void approach(Peer mover,Peer witness,Actor start,Actor board)throws Exception{
  var arena=ArenaMapCatalog.forMap(564);int[] dx={0,1,1,1,0,-1,-1,-1},dy={-1,-1,0,1,1,1,0,-1};var queue=new ArrayDeque<Long>();var prev=new HashMap<Long,long[]>();long first=((long)start.x()<<32)|(start.y()&0xffffffffL);queue.add(first);prev.put(first,new long[]{first,-1});long end=-1;
  Set<Long> occupied=new HashSet<>();for(byte[] packet:mover.received)if((packet[0]&255)==Protocol.S_PUT_OBJECT){Actor a=actor(packet);if(a.id()!=start.id())occupied.add(((long)a.x()<<32)|(a.y()&0xffffffffL));}
  while(!queue.isEmpty()&&prev.size()<20000){long point=queue.remove();int x=(int)(point>>32),y=(int)point;if(Math.max(Math.abs(x-board.x()),Math.abs(y-board.y()))<=5){end=point;break;}for(int h=0;h<8;h++){int nx=x+dx[h],ny=y+dy[h];long next=((long)nx<<32)|(ny&0xffffffffL);if(occupied.contains(next)||!arena.nativeCanStep(x,y,nx,ny))continue;if(prev.putIfAbsent(next,new long[]{point,h})==null)queue.add(next);}}
  require(end!=-1,"retained native arena edges reach server-issued board distance5");var path=new ArrayList<long[]>();for(long at=end;at!=first;at=prev.get(at)[0])path.add(new long[]{at,prev.get(at)[1]});Collections.reverse(path);List<Object> moves=new ArrayList<>();int x=start.x(),y=start.y();
  for(long[] step:path){int h=(int)step[1],nx=(int)(step[0]>>32),ny=(int)step[0];mover.send(new Protocol.Writer().c(Protocol.C_MOVE).h(x).h(y).c(h).bytes());byte[] actual=witness.await(Protocol.S_MOVE_OBJECT);require(Arrays.equals(actual,new Protocol.Writer().c(Protocol.S_MOVE_OBJECT).d(start.id()).h(nx).h(ny).c(h).bytes()),"normal C0A witnessed with actual mapped buyer ID");moves.add(Map.of("from_x",x,"from_y",y,"to_x",nx,"to_y",ny,"heading",h,"peer_hex",HexFormat.of().formatHex(actual)));sync(mover);x=nx;y=ny;}
  evidence.put("actual_house_board_approach",moves);evidence.put("actual_board_distance",Math.max(Math.abs(x-board.x()),Math.abs(y-board.y())));save();
 }
 byte[] exactMessage(Peer p,byte[] expected)throws Exception{for(int n=0;n<1000;n++){byte[] packet=p.await(Protocol.S_MESSAGE_CODE);if(Arrays.equals(packet,expected))return packet;}throw new AssertionError("expected actual native message absent");}
 @Override void portalFlow(ModernSettlementMysqlFixture mysql)throws Exception{
  start();snapshot(mysql,"before-T26-house-authentication");
  try(Peer holdA=select("HouseHolderA10001",port,"WireSend",SUN,"SenderA");Peer holdC=select("HouseHolderA10002",port,"WireHold",SUN,"HoldA");Peer buyer=select("HouseMappedBuyerB10001",port,"WireRecv",MOON,"RecvB");Peer seller=select("HouseMappedSellerB10002",port,"WireMate",MOON,"MateB")){
   beginBattle(buyer,seller,"MappedHouseAuction");Actor b=self(buyer,"WireRecv(WireMoon)"),s=self(seller,"WireMate(WireMoon)");require(b.id()==0x40000000L&&s.id()==0x40000001L,"both physical SQL house consumers use distinct mapped player wire IDs");evidence.put("actual_mapped_buyer",actorData(b));evidence.put("actual_mapped_seller",actorData(s));Actor board=null;for(byte[] x:buyer.received)if((x[0]&255)==Protocol.S_PUT_OBJECT){Actor a=actor(x);if(a.gfx()==1544&&a.name().equals("$1383"))board=a;}require(board!=null,"actual existing compatible house board actor");evidence.put("actual_server_issued_house_board",actorData(board));snapshot(mysql,"after-four-real-C9-and-legal-BATTLE");approach(buyer,seller,b,board);sync(buyer);sync(seller);require(adena(buyer)==500&&adena(seller)==20,"actual issued initial buyer/seller inventory");
   buyer.send(new Protocol.Writer().c(0x29).d(board.id()).bytes());byte[] list=buyer.await(0x73);var lr=new Protocol.Reader(list);lr.c();require(lr.d()==board.id()&&lr.h()==1&&lr.d()==HOUSE&&lr.s().equals("OwnedHouse")&&lr.h()==10,"actual one house list row");lr.c();lr.c();require(lr.d()==100&&lr.remaining()==0,"native bounded list and100 price");
   buyer.send(new Protocol.Writer().c(0x27).d(board.id()).s("select").s(Long.toString(HOUSE)).bytes());byte[] detail=buyer.await(0x2a);
   buyer.send(new Protocol.Writer().c(0x27).d(board.id()).s("apply").s(Long.toString(HOUSE)).bytes());byte[] input=buyer.await(0x5b);var ir=new Protocol.Reader(input);ir.c();require(ir.d()==board.id()&&ir.d()==0,"actual input board/auxiliary");long current=ir.d(),minimum=ir.d(),maximum=ir.d();int mode=ir.c();String prompt=ir.s(),html=ir.s(),callback=ir.s();require(current==100&&minimum==100&&maximum==2000000000L&&mode==0&&prompt.isEmpty()&&html.equals("agapply")&&callback.equals("agapply "+HOUSE)&&ir.h()==0&&ir.remaining()==0,"actual server-generated bid input context");
   byte[] bid=new Protocol.Writer().c(0x51).d(board.id()).d(current).c(mode).s(callback).bytes();buyer.send(bid);sync(buyer);require(adena(buyer)==400&&sqlAdena(mysql,10001)==400&&scalar(mysql,B,"SELECT COUNT(*) FROM `server_盟屋_拍賣` WHERE house_id="+HOUSE+" AND bidder_id=10001 AND bidder='RecvB' AND price=100")==1,"actual mapped buyer wire bid debits physical10001 selected sourceB");checks.add(Map.of("case","actual mapped buyer legal board bid","list_hex",HexFormat.of().formatHex(list),"detail_hex",HexFormat.of().formatHex(detail),"input_hex",HexFormat.of().formatHex(input),"bid_hex",HexFormat.of().formatHex(bid),"buyer_runtime_adena",adena(buyer),"buyer_SQL_adena",sqlAdena(mysql,10001)));snapshot(mysql,"after-actual-C51-physical-buyer-bid-SQL");
   long waitStart=System.nanoTime(),until=waitStart+TimeUnit.SECONDS.toNanos(400);boolean expiredSnapshot=false;List<Object> waits=new ArrayList<>();
   while(scalar(mysql,B,"SELECT COUNT(*) FROM `server_盟屋_拍賣` WHERE house_id="+HOUSE)!=0){long now=System.currentTimeMillis()/1000;require(System.nanoTime()<until,"real existing five-minute house settlement timer deadline");if(now>seededDeadline&&!expiredSnapshot){snapshot(mysql,"real-deadline-passed-before-existing-timer");expiredSnapshot=true;}waits.add(Map.of("observed_utc",Instant.now().toString(),"epoch_seconds",now,"elapsed_nanos",System.nanoTime()-waitStart));evidence.put("real_timer_wait",waits);stage="T26-real-house-timer-wait";save();Thread.sleep(5000);}
   byte[] won=exactMessage(buyer,Protocol.messageCode(524,"100","RecvB")),paid=exactMessage(seller,Protocol.messageCode(527,"90"));sync(buyer);sync(seller);require(adena(buyer)==400&&adena(seller)==110&&sqlAdena(mysql,10001)==400&&sqlAdena(mysql,10002)==110,"actual mapped buyer win and mapped old-owner payout inventory/SQL");require(scalar(mysql,B,"SELECT COUNT(*) FROM clan_data WHERE clan_id=70001 AND hashouse="+HOUSE)==1&&scalar(mysql,B,"SELECT COUNT(*) FROM clan_data WHERE clan_id=70002 AND hashouse=0")==1&&scalar(mysql,B,"SELECT COUNT(*) FROM `server_盟屋_紀錄` WHERE house_id="+HOUSE+" AND is_on_sale=0")==1,"normal timer physically transfers own selected source house");checks.add(Map.of("case","real timer settlement both mapped physical consumers","buyer_message_hex",HexFormat.of().formatHex(won),"seller_message_hex",HexFormat.of().formatHex(paid),"buyer_runtime_adena",adena(buyer),"seller_runtime_adena",adena(seller)));snapshot(mysql,"after-real-existing-timer-house-transfer-payout");
   buyer.close();Thread.sleep(500);snapshot(mysql,"after-mapped-buyer-normal-QUIT");seller.close();Thread.sleep(500);snapshot(mysql,"after-mapped-seller-normal-QUIT");holdC.close();holdA.close();
  }
  String log=serverLog();int conflicts=occurrences(log,"LiTo-private inventory SQL snapshot changed externally");evidence.put("actual_normal_disconnect_private_SQL_conflict_count",conflicts);evidence.put("normal_house_SQL_timer_passed",true);evidence.put("normal_SQL_persistence_success_count",occurrences(log,"MySQL Tournament disconnect inventory=SUCCESS"));stop();snapshot(mysql,"after-owned-normal-stop");evidence.put("Java_generations",1);evidence.put("old_TTL_or_clan_matrix_executed",false);evidence.put("product_clock_or_private_phase_changed",false);evidence.put("actual_native_BIN_or_GUI_executed",false);save();
 }
 @Override void run()throws Exception{super.run();evidence.put("state",((Number)evidence.get("actual_normal_disconnect_private_SQL_conflict_count")).intValue()>0?"QUALIFIED_T26_MAPPED_HOUSE_BID_SETTLEMENT_NORMAL_QUIT_PRIVATE_SQL_SNAPSHOT_CONFLICT":"PASSED_T26_MAPPED_HOUSE_BID_SETTLEMENT_NORMAL_QUIT_PHYSICAL_SQL");save();}
 public static void main(String[] args)throws Exception{new NativeMappedHouseAuctionWireMain(Path.of(args[0]),Path.of(args[1])).run();}
